def main():
    args = sys.argv[1:]
    as_json = False
    path = None
    for a in args:
        if a == '--json':
            as_json = True
        elif path is None:
            path = a
        else:
            sys.stderr.write('usage: stats.py [--json] FILE\\n')
            return 2
    if path is None:
        sys.stderr.write('usage: stats.py [--json] FILE\\n')
        return 2
    with open(path, 'r', encoding='utf-8') as f:
        text = f.read()
    lines = len(text.splitlines())
    words = len(text.split())
    chars = len(text)
    if as_json:
        print(json.dumps({'lines': lines, 'words': words, 'chars': chars}))
    else:
        print('%d %d %d %s' % (lines, words, chars, path))
    return 0

if __name__ == '__main__':
    sys.exit(main())
`;
