(function () {
  var state = { threeLoaded: false, rendererOk: false, renderError: null, frames: 0, startY: 0, t0: 0 };
  var scene = null, camera = null, cube = null, renderer = null;

  state.threeLoaded = !!(window.THREE && window.THREE.REVISION);

  if (state.threeLoaded) {
    scene = new THREE.Scene();
    scene.background = new THREE.Color(0x0b0e14);
    camera = new THREE.PerspectiveCamera(55, 1, 0.1, 100);
    camera.position.set(2.2, 2.2, 3.2);
    camera.lookAt(0, 0, 0);
    cube = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), new THREE.MeshNormalMaterial());
    cube.name = 'cube';
    scene.add(cube);
    state.startY = cube.rotation.y;
    try {
      renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setPixelRatio(1);
      renderer.setSize(320, 320);
      document.body.appendChild(renderer.domElement);
      state.rendererOk = true;
    } catch (e1) {
      try {
        renderer = new THREE.WebGLRenderer({ antialias: false });
        renderer.setSize(320, 320);
        document.body.appendChild(renderer.domElement);
        state.rendererOk = true;
      } catch (e2) {
        state.renderError = String((e2 && e2.message) || e2 || e1);
      }
    }
  }

  function frame(t) {
    state.frames++;
    if (!state.t0) state.t0 = t;
    if (cube) cube.rotation.y = ((t - state.t0) / 1000) * 0.9;
    if (renderer) renderer.render(scene, camera);
    requestAnimationFrame(frame);
  }
  if (state.threeLoaded) requestAnimationFrame(frame);

  window.__selfcheck = function () {
    var checks = [];
    function add(name, pass, evidence) { checks.push({ name: name, pass: !!pass, evidence: String(evidence) }); }
    add('three.js 已从 CDN 加载', state.threeLoaded, 'THREE.REVISION=' + (window.THREE && window.THREE.REVISION));
    add('场景中存在 cube（BoxGeometry 网格）',
      !!cube && scene.children.indexOf(cube) !== -1 && cube.geometry.type === 'BoxGeometry',
      cube ? ('name=' + cube.name + ', geometry=' + cube.geometry.type) : 'cube 未创建');
    add('WebGLRenderer 已就绪并挂载 canvas', state.rendererOk,
      state.rendererOk ? ('canvas ' + renderer.domElement.width + 'x' + renderer.domElement.height) : ('error: ' + state.renderError));
    add('动画循环已在运行', state.frames > 1, 'frames=' + state.frames);
    add('立方体绕 Y 轴自动旋转', !!cube && cube.rotation.y > state.startY + 0.05,
      'rotation.y: ' + state.startY.toFixed(3) + ' -> ' + (cube ? cube.rotation.y.toFixed(3) : 'n/a'));
    return { checks: checks, pass: checks.every(function (c) { return c.pass; }) };
  };

  var published = false;
  function publish() {
    if (published) return;
    published = true;
    var r = window.__selfcheck();
    document.getElementById('out').textContent =
      'SELFCHECK_JSON_START' + JSON.stringify(r) + 'SELFCHECK_JSON_END';
  }
  setTimeout(publish, 1500);
})();
</script>
</body>
</html>
`;

