function wsConnect(wsUrl) {
  return new Promise((resolve, reject) => {
    const u = new URL(wsUrl), key = crypto.randomBytes(16).toString('base64');
    const handlers = [];
    const sock = net.connect(Number(u.port), u.hostname, () => sock.write(
      `GET ${u.pathname} HTTP/1.1\r\nHost: ${u.host}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: ${key}\r\nSec-WebSocket-Version: 13\r\n\r\n`));
    let buf = Buffer.alloc(0), up = false;
    function send(str) {
      const d = Buffer.from(str, 'utf8'), mask = crypto.randomBytes(4);
      let h;
      if (d.length < 126) { h = Buffer.alloc(2); h[1] = 128 | d.length; }
      else { h = Buffer.alloc(4); h[1] = 128 | 126; h.writeUInt16BE(d.length, 2); }
      h[0] = 0x81;
      const m = Buffer.alloc(d.length); for (let i = 0; i < d.length; i++) m[i] = d[i] ^ mask[i % 4];
      sock.write(Buffer.concat([h, mask, m]));
    }
    sock.on('error', reject);
    sock.on('data', chunk => {
      buf = Buffer.concat([buf, chunk]);
      if (!up) {
        const i = buf.indexOf('\r\n\r\n'); if (i === -1) return;
        const status = buf.slice(0, i).toString().split('\r\n')[0];
        if (!/ 101 /.test(status + ' ')) return reject(new Error('ws handshake: ' + status));
        buf = buf.slice(i + 4); up = true;
        resolve({ send, onMessage: f => handlers.push(f), close: () => sock.destroy() });
      }
      while (up) {
        if (buf.length < 2) break;
        const op = buf[0] & 0x0f, b1 = buf[1]; let len = b1 & 127, off = 2;
        if (len === 126) { if (buf.length < 4) break; len = buf.readUInt16BE(2); off = 4; }
        else if (len === 127) { if (buf.length < 10) break; len = buf.readUInt32BE(2) * 4294967296 + buf.readUInt32BE(6); off = 10; }
        if (buf.length < off + len) break;
        const payload = buf.slice(off, off + len); buf = buf.slice(off + len);
        if (op === 1) handlers.forEach(f => f(payload.toString('utf8')));
      }
    });
  });
}

