const PY = `#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""stats.py — 统计文本文件的行数 / 词数 / 字符数（仅用 Python 标准库）

口径（固定，不要改）：
  1. 行数 = 文件内容按 '\\n' 切分后的段数（等价于 str.splitlines() 的长度）。
     末尾没有换行符时，最后一段仍然算作一行，即 行数 = '\\n' 的个数 + 1（非空文件）。
  2. 词数 = 按任意空白（含 Unicode 空白）切分后非空片段的数量（等价于 str.split() 的长度）。
  3. 字符数 = 按 UTF-8 解码后的字符串的 len()，包含所有空白、换行和标点；
     按 Unicode 码点计数，emoji 等 BMP 之外的字符每个计 1。

用法：
  python3 stats.py <file> [--json]      # --json 放在文件名前后都可以（argparse）

输出：
  默认（纯文本，stdout 三行，键名固定）：
    lines: N
    words: N
    chars: N
  --json：stdout 只有一行 JSON，{"lines": N, "words": N, "chars": N}
         任何提示/警告一律走 stderr，不允许污染 stdout。

退出码：
  0 成功；文件不存在 / 读不了 / 非 UTF-8 / 参数缺失 → stderr 打印错误，非零退出码。
"""

import argparse
import json
import sys


def build_parser():
    parser = argparse.ArgumentParser(
        prog="stats.py",
        description="统计文本文件的行数、词数、字符数。",
    )
    parser.add_argument("file", help="要统计的文本文件路径")
    parser.add_argument(
        "--json",
        action="store_true",
        help="以 JSON 形式输出到 stdout（stdout 中只有 JSON）",
    )
    return parser


def main(argv=None):
    args = build_parser().parse_args(argv)

    try:
        with open(args.file, "rb") as fh:
            raw = fh.read()
    except OSError as exc:
        print("stats.py: cannot read file %r: %s" % (args.file, exc), file=sys.stderr)
        return 1

    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        print("stats.py: %r is not valid UTF-8: %s" % (args.file, exc), file=sys.stderr)
        return 2

    lines = len(text.splitlines())
    words = len(text.split())
    chars = len(text)

    if args.json:
        sys.stdout.write(
            json.dumps({"lines": lines, "words": words, "chars": chars}) + "\\n"
        )
    else:
        sys.stdout.write("lines: %d\\nwords: %d\\nchars: %d\\n" % (lines, words, chars))
    return 0


if __name__ == "__main__":
    sys.exit(main())
`;

