// Outward test (criterion used): per triangle compute n = cross(v1-v0, v2-v0) and
// compare with the direction from the mesh vertex-centroid to the face centroid.
// n . (faceCentroid - vertexCentroid) < 0  =>  face winds inward.

function createCube() {
  const positions = [
    -0.5, -0.5, -0.5,
     0.5, -0.5, -0.5,
     0.5,  0.5, -0.5,
    -0.5,  0.5, -0.5,
    -0.5, -0.5,  0.5,
     0.5, -0.5,  0.5,
     0.5,  0.5,  0.5,
    -0.5,  0.5,  0.5
  ];
  const indices = [
    0, 2, 1,  0, 3, 2,
    4, 5, 6,  4, 6, 7,
    0, 1, 5,  0, 5, 4,
    3, 7, 6,  3, 6, 2,
    0, 4, 7,  0, 7, 3,
    1, 2, 6,  1, 6, 5
  ];
  return { positions: positions, indices: indices };
}

function audit(geometry) {
  const positions = geometry.positions;
  const indices = geometry.indices;
  const vertCount = Math.floor(positions.length / 3);
  const faces = Math.floor(indices.length / 3);

  let cx = 0, cy = 0, cz = 0;
  for (let v = 0; v < vertCount; v++) {
    cx += positions[v * 3];
    cy += positions[v * 3 + 1];
    cz += positions[v * 3 + 2];
  }
  cx /= vertCount; cy /= vertCount; cz /= vertCount;

  let inwardFaces = 0;
  for (let f = 0; f < faces; f++) {
    const i0 = indices[f * 3], i1 = indices[f * 3 + 1], i2 = indices[f * 3 + 2];
    const ax = positions[i0 * 3], ay = positions[i0 * 3 + 1], az = positions[i0 * 3 + 2];
    const bx = positions[i1 * 3], by = positions[i1 * 3 + 1], bz = positions[i1 * 3 + 2];
    const dx = positions[i2 * 3], dy = positions[i2 * 3 + 1], dz = positions[i2 * 3 + 2];
    const e1x = bx - ax, e1y = by - ay, e1z = bz - az;
    const e2x = dx - ax, e2y = dy - ay, e2z = dz - az;
    const nx = e1y * e2z - e1z * e2y;
    const ny = e1z * e2x - e1x * e2z;
    const nz = e1x * e2y - e1y * e2x;
    const mx = (ax + bx + dx) / 3 - cx;
    const my = (ay + by + dy) / 3 - cy;
    const mz = (az + bz + dz) / 3 - cz;
    if (nx * mx + ny * my + nz * mz < 0) inwardFaces++;
  }

  return {
    faces: faces,
    inwardFaces: inwardFaces,
    facesOutwardRatio: faces === 0 ? 1 : (faces - inwardFaces) / faces
  };
}

function main() {
  const g = createCube();
  const r = audit(g);
  console.log('cube: vertices=' + (g.positions.length / 3) + ' indices=' + g.indices.length);
  console.log('audit: faces=' + r.faces + ' inwardFaces=' + r.inwardFaces + ' ratio=' + r.facesOutwardRatio);
  console.log(JSON.stringify(r));
}

if (require.main === module) {
  main();
}

module.exports = { createCube: createCube, audit: audit };
`;

